import {dailyView,dailyDate,claimDaily,DAILY_REWARDS} from './daily-quests.mjs';
import {dailyArtStyle,dailyTaskFrame,dailyProgressFill,dailyNodeLeft} from './daily-ui-art.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderDailyBoard(profile,now=new Date()){
 const view=dailyView(profile,now),available=view.tasks.find(t=>t.complete&&!t.claimed),full=view.count>=3;
 return `<div class="daily-intro"><div><small>THE DAILY COVENANT</small><h2>每日委托</h2><p>完成任意三项，收下今日的秘境酬金。</p></div><div class="daily-total"><span>今日已领取</span><b>${view.total}<small> / 500 金币</small></b></div></div><section class="daily-rewards" aria-label="每日奖励进度"><div class="daily-rail" style="${dailyArtStyle('track')}"><div class="daily-progress" role="progressbar" aria-label="已领取任务" aria-valuemin="0" aria-valuemax="3" aria-valuenow="${view.count}"><i style="width:${dailyProgressFill(view.count)}%"></i></div>${DAILY_REWARDS.map((reward,i)=>{const opened=view.count>i,ready=!full&&view.count===i&&!!available;return `<button type="button" class="daily-chest ${opened?'opened':ready?'ready':'locked'}" style="left:${dailyNodeLeft(i)}%" data-daily-tier="${i}" ${!ready?'disabled':''} aria-label="第${i+1}个宝箱 ${reward}金币 ${opened?'已领取':ready?'可领取':'待完成任务'}"><i style="${dailyArtStyle('chest'+i+(opened?'Open':'Closed'))}"></i><b>${reward} <span>金币</span></b><small>${opened?'已领取':ready?'点击领取':`完成${i+1}项`}</small></button>`;}).join('')}</div></section><div class="daily-list-heading"><h3>今日委托 <small>五选三</small></h3><span>${esc(view.day)} · 每日 00:00 更新</span></div><div class="daily-task-list">${view.tasks.map((t,i)=>`<article class="daily-task ${t.claimed?'claimed':t.complete?'complete':''}" >${dailyTaskFrame()}<span class="daily-task-seal" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><div class="daily-task-copy"><h4>${t.name}</h4><p>${t.description}</p></div><span class="daily-task-count">${t.current}<small> / ${t.goal}</small></span><button type="button" data-daily-task="${t.id}" ${!t.complete||t.claimed||full?'disabled':''}>${t.claimed?'已领取':full?'奖励已领满':t.complete?'领取':'进行中'}</button></article>`).join('')}</div><p class="daily-bottom-note">第一份100金币 · 第二份100金币 · 第三份300金币</p>`;
}
export class DailyQuestDialog{
 constructor({getProfile,onSave,onOpen=()=>{},onClose=()=>{},now=()=>new Date()}){Object.assign(this,{getProfile,onSave,onOpen,onClose,now});this.dialog=document.createElement('dialog');this.dialog.className='daily-dialog';this.dialog.setAttribute('aria-label','每日任务');document.body.append(this.dialog);this.dialog.addEventListener('cancel',e=>{e.preventDefault();this.close();});this.dialog.addEventListener('close',()=>{clearInterval(this.timer);this.onClose();});this.dialog.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-daily-close'))return this.close();let id=b.dataset.dailyTask;if(b.dataset.dailyTier!==undefined){const v=dailyView(this.getProfile(),this.now());if(Number(b.dataset.dailyTier)!==v.count)return;id=v.tasks.find(t=>t.complete&&!t.claimed)?.id;}if(!id)return;try{const next=structuredClone(this.getProfile()),result=claimDaily(next,id,this.now());if(this.onSave(next)===false)throw Error('存档写入失败，奖励未领取，请重试');this.message=`获得 ${result.reward} 金币 · 今日累计 ${result.total} / 500`;}catch(error){this.message=error.message;}this.render();});}
 open(){if(this.dialog.open)return;this.onOpen();this.message='';this.render();this.dialog.showModal();this.timer=setInterval(()=>{if(dailyDate(this.now())!==this.day){this.message='新的委托已送达';this.render();}},10000);}
 close(){this.dialog.close();}
 render(){this.day=dailyDate(this.now());const p=this.getProfile();this.dialog.innerHTML=`<button class="daily-close" data-daily-close aria-label="关闭每日任务">×</button><div class="daily-board">${renderDailyBoard(p,this.now())}</div><footer class="daily-footer"><span role="status">${esc(this.message)||'本机保存当天进度，任选三项即可领满奖励'}</span><button data-daily-close>返回游戏 ›</button></footer>`;}
}
